package com.meterflow.metering;
import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="late_usage_adjustments",uniqueConstraints=@UniqueConstraint(columnNames="usage_event_id"))
public class LateUsageAdjustment {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="usage_event_id",nullable=false,unique=true) private UUID usageEventId;@Column(nullable=false) private String customerId;@Column(nullable=false) private String billingPeriod;@Column(nullable=false) private String status="PENDING";@Column(nullable=false) private Instant createdAt=Instant.now();protected LateUsageAdjustment(){}public LateUsageAdjustment(UUID event,String customer,String period){usageEventId=event;customerId=customer;billingPeriod=period;}public UUID getId(){return id;}public UUID getUsageEventId(){return usageEventId;}public String getCustomerId(){return customerId;}public String getBillingPeriod(){return billingPeriod;}public String getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public void markInvoiced(){status="INVOICED";}}
